Here is the commit message:
drm/amdkfd: Fix memory leak in create_process failure

Fix memory leak due to a leaked mmget reference on an error handling
code path that is triggered when attempting to create KFD processes
while a GPU reset is in progress.

Fixes: 0ab2d7532b05 ("drm/amdkfd: prepare per-process debug enable and disable")
CC: Xiaogang Chen <xiaogang.chen@amd.com>
Signed-off-by: Felix Kuehling <felix.kuehling@amd.com>
Tested-by: Harish Kasiviswanthan <Harish.Kasiviswanthan@amd.com>
Reviewed-by: Mukul Joshi <mukul.joshi@amd.com>
Signed-off-by: Alex Deucher <alexander.deucher@amd.com>
Cc: stable@vger.kernel.org

Here is the root cause:
The bug is caused by a memory leak due to a leaked mmget reference when the KFD (Kernel Fusion Driver) is locked and an attempt to create a process fails. The original code prematurely unlocked the mutex without properly handling the error case, leading to the failure to release the memory reference associated with the process creation.

Here is the patch:

 struct kfd_process *kfd_create_process(struct task_struct *thread)
 {
 	struct kfd_process *process;
 	int ret;

 	if (!(thread->mm && mmget_not_zero(thread->mm)))
 		return ERR_PTR(-EINVAL);

 	/* Only the pthreads threading model is supported. */
 	if (thread->group_leader->mm != thread->mm) {
 		mmput(thread->mm);
 		return ERR_PTR(-EINVAL);
 	}

 	/*
 	 * take kfd processes mutex before starting of process creation
 	 * so there won't be a case where two threads of the same process
 	 * create two kfd_process structures
 	 */
 	mutex_lock(&kfd_processes_mutex);

 	if (kfd_is_locked()) {
-		mutex_unlock(&kfd_processes_mutex);
 		pr_debug("KFD is locked! Cannot create process");
-		return ERR_PTR(-EINVAL);
+		process = ERR_PTR(-EINVAL);
+		goto out;
 	}

 	/* A prior open of /dev/kfd could have already created the process. */
 	process = find_process(thread, false);
 	if (process) {
 		pr_debug("Process already found\n");
 	} else {
 		process = create_process(thread);
 		if (IS_ERR(process))
 			goto out;

 		if (!procfs.kobj)
 			goto out;

 		process->kobj = kfd_alloc_struct(process->kobj);
 		if (!process->kobj) {
 			pr_warn("Creating procfs kobject failed");
 			goto out;
 		}
 		ret = kobject_init_and_add(process->kobj, &procfs_type,
 					   procfs.kobj, "%d",
 					   (int)process->lead_thread->pid);
 		if (ret) {
 			pr_warn("Creating procfs pid directory failed");
 			kobject_put(process->kobj);
 			goto out;
 		}

 		kfd_sysfs_create_file(process->kobj, &process->attr_pasid,
 				      "pasid");

 		process->kobj_queues = kobject_create_and_add("queues",
 							process->kobj);
 		if (!process->kobj_queues)
 			pr_warn("Creating KFD proc/queues folder failed");

 		kfd_procfs_add_sysfs_stats(process);
 		kfd_procfs_add_sysfs_files(process);
 		kfd_procfs_add_sysfs_counters(process);

 		init_waitqueue_head(&process->wait_irq_drain);
 	}
 out:
 	if (!IS_ERR(process))
 		kref_get(&process->ref);
 	mutex_unlock(&kfd_processes_mutex);
 	mmput(thread->mm);

 	return process;
 }



